/bin/bash -lc "head -30 brain.vti; python - <<'PY'
try:
 import vtk
 print('VTK',vtk.vtkVersion.GetVTKVersion())
except Exception as e: print('no vtk',e)
try:
 import paraview
 print('paraview yes')
except Exception as e: print('no paraview',e)
PY
find / -iname 'pvpython*' -o -iname 'paraview' 2>/dev/null | head -30"

